CREATE TABLE IF NOT EXISTS capital_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, account_code text NOT NULL, account_name text NOT NULL, capital_type text NOT NULL, authorized_amount numeric(24,2), currency text NOT NULL DEFAULT 'NGN', paid_in_amount numeric(24,2) DEFAULT 0, status text NOT NULL DEFAULT 'Proposed', legal_basis text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS treasury_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, account_name text NOT NULL, institution_name text, account_type text NOT NULL, currency text NOT NULL DEFAULT 'NGN', mandate_level text, signatory_rule text, status text NOT NULL DEFAULT 'Proposed', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS treasury_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, policy_code text NOT NULL, policy_name text NOT NULL, control_requirement text NOT NULL, approval_route text, segregation_requirement text, review_frequency text, status text NOT NULL DEFAULT 'Proposed', legal_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS institutional_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, asset_code text NOT NULL, asset_name text NOT NULL, asset_type text NOT NULL, jurisdiction text, ownership_basis text, title_or_right_reference text, custodian text, valuation_amount numeric(24,2), valuation_currency text, valuation_date date, encumbrance_status text NOT NULL DEFAULT 'None Recorded', status text NOT NULL DEFAULT 'Proposed', legal_review_required boolean NOT NULL DEFAULT true, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_interests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES institutional_assets(id) ON DELETE CASCADE, interest_type text NOT NULL, holder_type text NOT NULL, holder_reference text, percentage numeric(8,4), economic_right text, voting_or_control_right text, protection_reference text, status text NOT NULL DEFAULT 'Proposed', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_encumbrances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES institutional_assets(id) ON DELETE CASCADE, encumbrance_type text NOT NULL, secured_party text, amount numeric(24,2), currency text, priority text, instrument_reference text, start_date date, end_date date, status text NOT NULL DEFAULT 'Proposed', legal_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES institutional_assets(id) ON DELETE CASCADE, transaction_type text NOT NULL, counterparty text, amount numeric(24,2), currency text, approval_route text, approved_by text, transaction_date date, evidence_reference text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stewardship_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, rule_code text NOT NULL, rule_name text NOT NULL, asset_scope text NOT NULL, requirement text NOT NULL, community_or_indigenous_trigger text, approval_trigger text, audit_requirement text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS distributions_and_reserves (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, policy_type text NOT NULL, policy_name text NOT NULL, trigger_condition text, priority_order text, beneficiary_scope text, reserve_requirement text, approval_route text, status text NOT NULL DEFAULT 'Proposed', legal_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO capital_accounts(entity_name,account_code,account_name,capital_type,currency,legal_basis) SELECT 'OSANVAULT AFRICA LTD','SC-ORD','Ordinary Share Capital','Share Capital','NGN','To be reconciled with CAC filings and adopted articles.' WHERE NOT EXISTS (SELECT 1 FROM capital_accounts WHERE account_code='SC-ORD');
INSERT INTO treasury_policies(entity_name,policy_code,policy_name,control_requirement,approval_route,segregation_requirement,review_frequency) SELECT 'OSANVAULT AFRICA LTD','TR-01','Treasury Segregation','Payment initiation, approval and reconciliation should be separated according to risk and authority thresholds.','Board-approved treasury policy.','Maker-checker principle.','Quarterly' WHERE NOT EXISTS (SELECT 1 FROM treasury_policies WHERE policy_code='TR-01');
INSERT INTO treasury_policies(entity_name,policy_code,policy_name,control_requirement,approval_route,segregation_requirement,review_frequency) SELECT 'OSANVAULT AFRICA LTD','TR-02','Asset Custody','Institutional assets must have a named custodian, evidence trail and periodic reconciliation.','Board/authorized asset committee.','Custody separated from unauthorized disposition.','Quarterly' WHERE NOT EXISTS (SELECT 1 FROM treasury_policies WHERE policy_code='TR-02');
INSERT INTO treasury_policies(entity_name,policy_code,policy_name,control_requirement,approval_route,segregation_requirement,review_frequency) SELECT 'OSANVAULT AFRICA LTD','TR-03','Material Disposal Gate','Material asset disposals require documented valuation, conflict review, reserved-matter classification and required approvals.','Reserved Matters Engine + Board/shareholder route where applicable.','Initiator separate from approver.','Per transaction' WHERE NOT EXISTS (SELECT 1 FROM treasury_policies WHERE policy_code='TR-03');
INSERT INTO stewardship_rules(entity_name,rule_code,rule_name,asset_scope,requirement,community_or_indigenous_trigger,approval_trigger,audit_requirement) SELECT 'OSANVAULT AFRICA LTD','AS-01','Protected Asset Stewardship','Land, mineral, carbon, cultural or community-linked assets','Maintain title/right evidence, valuation, custodian, restrictions and transaction history.','Any documented indigenous/customary/community interest.','Reserved-matter review before material transfer or encumbrance.','Annual independent review.' WHERE NOT EXISTS (SELECT 1 FROM stewardship_rules WHERE rule_code='AS-01');
INSERT INTO distributions_and_reserves(entity_name,policy_type,policy_name,trigger_condition,priority_order,beneficiary_scope,reserve_requirement,approval_route) SELECT 'OSANVAULT AFRICA LTD','Reserve','Institutional Reserves','Before discretionary distributions where required by law, financing terms or board policy.','Statutory/contractual obligations → required reserves → approved distributions.','Shareholders and other legally entitled beneficiaries.','To be determined by adopted financial policy.','Board/shareholder route as applicable.' WHERE NOT EXISTS (SELECT 1 FROM distributions_and_reserves WHERE policy_name='Institutional Reserves');